//! `levels/ffa_hive.lvl` (generated by `scripts/gen_hive_level.py`): THE HIVE, a 56 x 56 m honeycomb shaft, 190 m tall, no
//! ground, built only from bricks. Pinned: box budget, destructible share, nine ring floors one 20 m apart joined by 24 degree
//! ramps into ONE walkable network that holds every spawn (a multi-layer flood: floors stack over each other, so a plain
//! heightmap would only see the roof), the hook-only places (crown, swing lines, roof), hook anchors everywhere, supported
//! pickups, engine limits.

use shinobi_sim::character::{Cfg, PhysicsWorld};
use shinobi_sim::level::{is_floating, parse_level_file, LevelBox, LevelFile};
use shinobi_sim::pvp::KILL_PLANE_Y;
use shinobi_sim::rapier3d::prelude::*;
use shinobi_sim::spawn::far_dist;
use std::collections::{HashMap, VecDeque};

const FLOORS: usize = 9;
fn deck(k: usize) -> f32 {
    10.0 + 20.0 * k as f32
}

fn load() -> LevelFile {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../levels/ffa_hive.lvl");
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    parse_level_file(&text).unwrap_or_else(|e| panic!("ffa_hive.lvl: {e}"))
}

fn world(l: &LevelFile) -> PhysicsWorld {
    let mut w = PhysicsWorld { bodies: RigidBodySet::new(), colliders: ColliderSet::new(), islands: IslandManager::new(), queries: QueryPipeline::new() };
    l.level.insert_into(&mut w);
    w.queries.update(&w.colliders);
    w
}

fn inside(b: &LevelBox, p: [f32; 3]) -> bool {
    let (s, c) = b.rot_z.sin_cos();
    let (dx, dy) = (p[0] - b.center[0], p[1] - b.center[1]);
    let (u, v) = (dx * c + dy * s, -dx * s + dy * c);
    u.abs() <= b.half[0] && v.abs() <= b.half[1] && (p[2] - b.center[2]).abs() <= b.half[2]
}

/// (bottom, top) of box `b` over (x, z), rolled boxes give their slope.
fn span_at(b: &LevelBox, x: f32, z: f32) -> Option<(f32, f32)> {
    if (z - b.center[2]).abs() > b.half[2] {
        return None;
    }
    let (s, c) = b.rot_z.sin_cos();
    let u = (x - b.center[0] + b.half[1] * s) / c;
    (u.abs() <= b.half[0]).then(|| {
        let top = b.center[1] + u * s + b.half[1] * c;
        (top - 2.0 * b.half[1] / c, top)
    })
}

fn d3(a: [f32; 3], b: [f32; 3]) -> f32 {
    ((a[0] - b[0]).powi(2) + (a[1] - b[1]).powi(2) + (a[2] - b[2]).powi(2)).sqrt()
}

fn vol(b: &LevelBox) -> f32 {
    8.0 * b.half[0] * b.half[1] * b.half[2]
}

#[test]
fn the_hive_has_sixteen_spawns_on_many_floors_six_cubes_two_bows_and_four_tag_bags() {
    let l = load();
    assert!((1200..=1800).contains(&l.level.boxes.len()), "{} boxes", l.level.boxes.len());
    assert!((14..=18).contains(&l.level.spawns.len()), "{} spawns", l.level.spawns.len());
    let cubes = l.pickups.iter().filter(|p| p.kind == shinobi_sim::power::PowerKind::None).count();
    let yumi = l.pickups.iter().filter(|p| p.kind == shinobi_sim::power::PowerKind::Yumi).count();
    let tags = l.pickups.iter().filter(|p| p.kind == shinobi_sim::power::PowerKind::Tag).count();
    assert_eq!((cubes, yumi, tags), (6, 2, 4), "cubes / bows / tag bags");
    assert!(l.pickups.iter().filter(|p| p.kind != shinobi_sim::power::PowerKind::None).all(|p| p.respawn_secs == 45.0));
    assert!(l.pickups.iter().filter(|p| p.kind == shinobi_sim::power::PowerKind::Yumi).all(|p| p.pos[1] > 100.0), "bows sit high");
    assert!(l.pickups.iter().filter(|p| p.kind == shinobi_sim::power::PowerKind::Tag).all(|p| p.pos[1] < 100.0), "tag bags sit low / mid");
    let mut heights: Vec<i32> = l.level.spawns.iter().map(|s| (s[1] - 0.81).round() as i32).collect();
    heights.sort();
    heights.dedup();
    assert!(heights.len() >= 5, "spawns on only {} heights", heights.len());
    assert!(heights.iter().all(|h| (0..FLOORS).any(|k| *h == deck(k) as i32)), "a spawn is not on a deck: {heights:?}");
}

#[test]
fn it_is_a_floating_shaft_at_least_170_m_tall_with_the_kill_plane_far_below() {
    let l = load();
    assert!(is_floating(&l.level), "no box may reach down toward y = 0");
    let lowest = l.level.boxes.iter().map(|b| b.center[1] - b.half[1]).fold(f32::MAX, f32::min);
    assert!(lowest >= 8.0 && lowest - KILL_PLANE_Y >= 26.0, "lowest body y = {lowest}, kill plane {KILL_PLANE_Y}");
    assert_eq!(l.level.floor_half(), None, "no floor slab");
    let top = l.level.boxes.iter().map(|b| b.center[1] + b.half[1]).fold(0.0, f32::max);
    assert!((170.0..=200.0).contains(&top), "tallest geometry {top} m");
}

#[test]
fn nearly_everything_is_a_destructible_brick_and_bedrock_is_only_the_plinths() {
    let l = load();
    let total: f32 = l.level.boxes.iter().map(vol).sum();
    let dest: f32 = l.level.boxes.iter().filter(|b| b.hp > 0.0).map(vol).sum();
    assert!(dest / total >= 0.70, "only {:.0} % of the volume is destructible", 100.0 * dest / total);
    let perm: Vec<&LevelBox> = l.level.boxes.iter().filter(|b| b.hp == 0.0).collect();
    // bedrock: a plate under each spawn / pedestal (a spawn on a plate seam takes two) and the two plinths
    assert!(perm.len() <= 2 * l.level.spawns.len() + 2 * l.pickups.len() + 4, "{} permanent boxes", perm.len());
    for b in &perm {
        let near = |p: [f32; 3]| inside(&LevelBox { half: [b.half[0] + 0.7, b.half[1] + 1.2, b.half[2] + 0.7], ..**b }, p);
        let under_spawn = l.level.spawns.iter().any(|s| near([s[0], s[1] - 0.81, s[2]]));
        let under_pickup = l.pickups.iter().any(|p| near([p.pos[0], p.pos[1] - 1.0, p.pos[2]]));
        assert!(under_spawn || under_pickup, "permanent box {b:?} is not under a spawn or pedestal");
    }
    // bricks: 2..6 m on a side (girders and the hung chains' links excepted: a handful of long thin boxes)
    let mut girders = 0;
    for b in l.level.boxes.iter().filter(|b| b.hp > 0.0 && b.rot_z == 0.0) {
        let d = [2.0 * b.half[0], 2.0 * b.half[1], 2.0 * b.half[2]];
        if d.iter().cloned().fold(0.0, f32::max) > 6.01 {
            girders += 1;
        } else {
            assert!(d.iter().cloned().fold(f32::MAX, f32::min) >= 1.9, "sliver brick {b:?}");
        }
    }
    assert!(girders <= 32, "{girders} long girders");
}

#[test]
fn spawns_stand_on_a_deck_clear_of_geometry_and_not_stacked() {
    let l = load();
    let cfg = Cfg::default();
    let reach = cfg.half_height + cfg.radius;
    for s in &l.level.spawns {
        for dy in [-reach + 0.05, -0.3, 0.0, 0.3, reach - 0.05] {
            for (ox, oz) in [(0.0, 0.0), (cfg.radius, 0.0), (-cfg.radius, 0.0), (0.0, cfg.radius), (0.0, -cfg.radius)] {
                let p = [s[0] + ox, s[1] + dy, s[2] + oz];
                assert!(!l.level.boxes.iter().any(|b| inside(b, p)), "spawn {s:?}: capsule point {p:?} is inside geometry");
            }
        }
        let on = l.level.boxes.iter().any(|b| span_at(b, s[0], s[2]).map_or(false, |(_, t)| (t - (s[1] - reach)).abs() < 0.1));
        assert!(on, "spawn {s:?} floats or is buried");
        assert!(l.level.boxes.iter().any(|b| b.hp == 0.0 && span_at(b, s[0], s[2]).map_or(false, |(_, t)| (t - (s[1] - reach)).abs() < 0.1)), "spawn {s:?} has no bedrock plinth");
    }
    let n = l.level.spawns.len();
    let nearest: Vec<f32> = (0..n).map(|i| (0..n).filter(|j| *j != i).map(|j| d3(l.level.spawns[i], l.level.spawns[j])).fold(f32::MAX, f32::min)).collect();
    let min = nearest.iter().copied().fold(f32::MAX, f32::min);
    assert!(min >= 9.0, "two spawns only {min:.1} m apart");
    let far = far_dist(&l.level.spawns);
    assert!((20.0..=70.0).contains(&far), "preferred respawn distance {far:.1} m");
}

/// Walkable surfaces per 1 m cell: every box top with 2.2 m of headroom above it (floors stack, so a cell has many).
fn surfaces(l: &LevelFile) -> HashMap<(i32, i32), Vec<f32>> {
    let mut out = HashMap::new();
    for x in -30..30 {
        for z in -30..30 {
            let (px, pz) = (x as f32 + 0.5, z as f32 + 0.5);
            let spans: Vec<(f32, f32)> = l.level.boxes.iter().filter_map(|b| span_at(b, px, pz)).collect();
            let mut tops: Vec<f32> = Vec::new();
            for (i, (_, top)) in spans.iter().enumerate() {
                let blocked = spans.iter().enumerate().any(|(j, (b2, t2))| j != i && *b2 < top + 2.2 && *t2 > top + 0.3);
                if !blocked && !tops.iter().any(|t| (t - top).abs() < 0.1) {
                    tops.push(*top);
                }
            }
            if !tops.is_empty() {
                out.insert((x, z), tops);
            }
        }
    }
    out
}

/// Flood over (cell, surface): neighbours connect when the surfaces differ by <= 0.5 m. One component holds every spawn and the
/// feet of all nine floors; the crown, the swing lines and the roof are real surfaces that are NOT in it (hook / wall-run only).
#[test]
fn one_walkable_network_joins_every_spawn_and_floor_and_the_high_places_stay_disconnected() {
    let l = load();
    let cells = surfaces(&l);
    let reach = Cfg::default().half_height + Cfg::default().radius;
    let node_of = |p: [f32; 3]| -> ((i32, i32), f32) {
        let c = (p[0].floor() as i32, p[2].floor() as i32);
        let h = cells[&c].iter().cloned().min_by(|a, b| (a - (p[1] - reach)).abs().partial_cmp(&(b - (p[1] - reach)).abs()).unwrap()).unwrap();
        (c, h)
    };
    let mut seen: HashMap<(i32, i32), Vec<f32>> = HashMap::new();
    let start = node_of(l.level.spawns[0]);
    let mut q = VecDeque::from([start]);
    seen.entry(start.0).or_default().push(start.1);
    while let Some((c, y)) = q.pop_front() {
        for (dx, dz) in [(1, 0), (-1, 0), (0, 1), (0, -1)] {
            let nc = (c.0 + dx, c.1 + dz);
            let Some(hs) = cells.get(&nc) else { continue };
            for &ny in hs {
                if (ny - y).abs() <= 0.5 && !seen.get(&nc).map_or(false, |v| v.iter().any(|h| (h - ny).abs() < 0.01)) {
                    seen.entry(nc).or_default().push(ny);
                    q.push_back((nc, ny));
                }
            }
        }
    }
    let reached = |c: &(i32, i32), h: f32| seen.get(c).map_or(false, |v| v.iter().any(|x| (x - h).abs() < 0.01));
    for s in &l.level.spawns {
        let (c, h) = node_of(*s);
        assert!(reached(&c, h), "spawn {s:?} cannot walk to the rest of the hive");
    }
    for k in 0..FLOORS {
        let n = seen.values().flatten().filter(|h| (**h - deck(k)).abs() < 0.1).count();
        assert!(n >= 250, "floor {k} (y = {}): only {n} reachable cells", deck(k));
    }
    // ramp cells between the decks: the climb is walkable, not a jump
    let between = seen.values().flatten().filter(|h| (10.5..169.5).contains(*h) && (0..FLOORS).all(|k| (**h - deck(k)).abs() > 0.5)).count();
    assert!(between >= 8 * 60, "only {between} ramp cells reached");
    let off = |lo: f32, hi: f32| -> (usize, usize) {
        let mut all = 0;
        let mut walk = 0;
        for (c, hs) in &cells {
            for h in hs.iter().filter(|h| (lo..hi).contains(*h)) {
                all += 1;
                walk += reached(c, *h) as usize;
            }
        }
        (all, walk)
    };
    let (crown, crown_w) = off(164.9, 165.1);
    assert!(crown >= 20 && crown_w == 0, "crown: {crown} cells, {crown_w} walkable");
    let (roof, roof_w) = off(189.9, 190.1);
    assert!(roof >= 800 && roof_w == 0, "roof: {roof} cells, {roof_w} walkable");
    let mut swing = 0;
    for k in 0..FLOORS - 1 {
        let (n, w) = off(deck(k) + 10.7, deck(k) + 10.8);
        assert!(n >= 20 && w == 0, "swing line above floor {k}: {n} cells, {w} walkable");
        swing += n;
    }
    assert!(swing >= 8 * 20);
}

/// Hook anchors: from every spawn and from a grid of walkable points, at least 3 distinct boxes lie within 30 m of the head
/// (the grapple reaches 1000 m; the ceiling alone is one box every 20 m).
#[test]
fn at_least_three_hook_anchors_are_within_30_m_everywhere() {
    let l = load();
    let near = |p: [f32; 3]| -> usize {
        l.level
            .boxes
            .iter()
            .filter(|b| {
                let e = [(p[0] - b.center[0]).abs() - b.half[0].max(b.half[1]), (p[1] - b.center[1]).abs() - b.half[1].max(b.half[0]), (p[2] - b.center[2]).abs() - b.half[2]];
                let d = (e[0].max(0.0).powi(2) + e[1].max(0.0).powi(2) + e[2].max(0.0).powi(2)).sqrt();
                d <= 30.0 && b.center[1] + b.half[1] > p[1] - 1.5 // above the feet, so it can lift a swing
            })
            .count()
    };
    for s in &l.level.spawns {
        assert!(near([s[0], s[1] + 0.7, s[2]]) >= 3, "spawn {s:?}: fewer than 3 hook anchors within 30 m");
    }
    for k in 0..FLOORS {
        for x in [-24.0, -8.0, 0.0, 8.0, 24.0] {
            for z in [-24.0, -8.0, 0.0, 8.0, 24.0] {
                let p = [x, deck(k) + 1.5, z];
                assert!(near(p) >= 3, "{p:?}: fewer than 3 hook anchors within 30 m");
            }
        }
    }
}

#[test]
fn the_well_is_open_and_the_walls_are_closed() {
    let l = load();
    // nothing in the well except the two 4 m stripes (the bots' heightmap edge guard needs the void elsewhere)
    for b in l.level.boxes.iter().filter(|b| b.center[1] + b.half[1] < 188.0) {
        let in_well = (b.center[0].abs() - b.half[0]) < 16.5 && (b.center[2].abs() - b.half[2]) < 16.5 && b.rot_z == 0.0;
        let stripe = (b.center[0].abs() + b.half[0]) <= 4.01 || (b.center[2].abs() + b.half[2]) <= 4.01;
        let in_rim = (b.center[0].abs() - b.half[0]) >= 15.5 || (b.center[2].abs() - b.half[2]) >= 15.5;
        assert!(!in_well || stripe || in_rim, "box {b:?} sits in the open well outside the stripes");
    }
    let tall_walls = l.level.boxes.iter().filter(|b| b.rot_z == 0.0 && b.half[1] * 2.0 >= 5.9 && (b.center[0].abs() > 26.5 || b.center[2].abs() > 26.5)).count();
    assert!(tall_walls >= 500, "{tall_walls} wall bricks");
}

#[test]
fn pickups_are_supported_and_not_inside_geometry() {
    let l = load();
    for p in &l.pickups {
        assert!(!l.level.boxes.iter().any(|b| inside(b, p.pos)), "pickup {:?} is inside geometry", p.pos);
        let supported = l.level.boxes.iter().any(|b| span_at(b, p.pos[0], p.pos[2]).map_or(false, |(_, h)| (p.pos[1] - h - 1.0).abs() < 0.3));
        assert!(supported, "pickup {:?} is not ~1 m above a surface", p.pos);
    }
}

#[test]
fn engine_numeric_limits_cover_the_map() {
    let l = load();
    let far = l.level.boxes.iter().map(|b| b.center[0].abs() + b.half[0]).chain(l.level.boxes.iter().map(|b| b.center[2].abs() + b.half[2])).fold(0.0, f32::max);
    assert!(far <= 125.0, "geometry reaches {far} m sideways");
    let q = shinobi_proto::quant::q_pos3([2.0 * far, 195.0, 2.0 * far]);
    let back = shinobi_proto::quant::dq_pos3(q);
    assert!((back[0] - 2.0 * far).abs() < 0.01 && (back[1] - 195.0).abs() < 0.01, "q_pos3 loses precision");
    let w = world(&l);
    assert_eq!(w.colliders.len(), l.level.boxes.len());
}
